<?php require __DIR__.'/../config/config.php';require __DIR__.'/../config/helpers.php';require_role('hotelier');$uid=current_user()['id'];$q=$pdo->prepare('SELECT * FROM hotels WHERE user_id=? ORDER BY id DESC LIMIT 1');$q->execute([$uid]);$hotel=$q->fetch();if(!$hotel){flash('warning','Aucun hôtel associé à ce compte.');redirect('register.php?role=hotelier');}$hid=$hotel['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='profile'){$q=$pdo->prepare('UPDATE hotels SET nom=?,description=?,adresse=?,ville=?,commune=?,telephone=?,email=?,categorie=?,etoiles=? WHERE id=? AND user_id=?');$q->execute([trim($_POST['nom']??''),trim($_POST['description']??''),trim($_POST['adresse']??''),trim($_POST['ville']??''),trim($_POST['commune']??''),trim($_POST['telephone']??''),trim($_POST['email']??''),$_POST['categorie']??'Hôtel',max(0,min(5,(int)($_POST['etoiles']??0))),$hid,$uid]);flash('success','Profil hôtel mis à jour. Il devra être revalidé si nécessaire.');}elseif($action==='room'){$nom=trim($_POST['room_nom']??'');$type=trim($_POST['type']??'Chambre double');$price=(float)($_POST['prix_nuit']??0);$capacity=max(1,min(10,(int)($_POST['capacite']??2)));$qty=max(1,min(50,(int)($_POST['quantite']??1)));if($nom&&$price>0){$q=$pdo->prepare('INSERT INTO rooms(hotel_id,nom,type,description,capacite,lits,prix_nuit,quantite) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$hid,$nom,$type,trim($_POST['description_chambre']??''),$capacity,max(1,(int)($_POST['lits']??1)),$price,$qty]);flash('success','Chambre ajoutée.');}else flash('danger','Indiquez un nom de chambre et un prix valide.');}redirect('hotel/index.php');}$q=$pdo->prepare('SELECT * FROM rooms WHERE hotel_id=? ORDER BY id DESC');$q->execute([$hid]);$rooms=$q->fetchAll();$q=$pdo->prepare('SELECT r.*,u.nom,u.prenom,rm.nom chambre FROM reservations r JOIN users u ON u.id=r.user_id JOIN rooms rm ON rm.id=r.room_id WHERE r.hotel_id=? ORDER BY r.created_at DESC LIMIT 100');$q->execute([$hid]);$reservations=$q->fetchAll();$q=$pdo->prepare("SELECT COUNT(*) FROM reservations WHERE hotel_id=? AND statut NOT IN ('annulee','refusee')");$q->execute([$hid]);$total=$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM reservations WHERE hotel_id=? AND statut IN ('payee','terminee')");$q->execute([$hid]);$revenue=$q->fetchColumn();$pageTitle='Espace hôtelier';require __DIR__.'/../includes/header.php';?><section class="dashboard"><div class="container"><div class="dash-title"><div><span class="eyebrow">ESPACE HÔTELIER</span><h1><?=e($hotel['nom'])?></h1><p class="muted">Gérez vos chambres et suivez vos réservations.</p></div><span class="badge-status">Statut : <?=e($hotel['statut'])?></span></div><?php if($hotel['statut']!=='valide'):?><div class="alert alert-warning">Votre hôtel n’est pas encore publié. Il apparaîtra dans la recherche après validation de l’administrateur.</div><?php endif;?><div class="stat-grid"><div class="stat-card"><small>Réservations actives</small><strong><?=$total?></strong></div><div class="stat-card"><small>Chambres</small><strong><?=count($rooms)?></strong></div><div class="stat-card"><small>Revenus payés / terminés</small><strong><?=money($revenue)?></strong></div><div class="stat-card"><small>Réservations en attente</small><strong><?=count(array_filter($reservations,fn($r)=>$r['statut']==='attente'))?></strong></div></div><div class="panel"><h2>Profil de l’établissement</h2><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="profile"><div class="col-md-6"><label class="form-label">Nom de l’hôtel</label><input class="form-control" name="nom" required value="<?=e($hotel['nom'])?>"></div><div class="col-md-3"><label class="form-label">Ville</label><input class="form-control" name="ville" required value="<?=e($hotel['ville'])?>"></div><div class="col-md-3"><label class="form-label">Commune</label><input class="form-control" name="commune" value="<?=e($hotel['commune'])?>"></div><div class="col-md-6"><label class="form-label">Adresse</label><input class="form-control" name="adresse" value="<?=e($hotel['adresse'])?>"></div><div class="col-md-3"><label class="form-label">Téléphone</label><input class="form-control" name="telephone" value="<?=e($hotel['telephone'])?>"></div><div class="col-md-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=e($hotel['email'])?>"></div><div class="col-md-6"><label class="form-label">Catégorie</label><select class="form-select" name="categorie"><?php foreach(['Hôtel','Résidence','Appartement hôtel','Auberge','Complexe hôtelier','Villa','Resort'] as $c):?><option <?=$hotel['categorie']===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Étoiles (0 à 5)</label><select class="form-select" name="etoiles"><?php for($i=0;$i<=5;$i++):?><option value="<?=$i?>" <?=$hotel['etoiles']==$i?'selected':''?>><?=$i?></option><?php endfor;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"><?=e($hotel['description'])?></textarea></div><div class="col-12"><button class="btn btn-primary">Enregistrer le profil</button></div></form></div><div class="panel"><h2>Ajouter une chambre</h2><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="room"><div class="col-md-4"><label class="form-label">Nom</label><input class="form-control" name="room_nom" required placeholder="Chambre 101"></div><div class="col-md-4"><label class="form-label">Type</label><select class="form-select" name="type"><?php foreach(['Chambre simple','Chambre double','Chambre triple','Suite','Suite familiale','Chambre VIP'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Prix par nuit (FCFA)</label><input class="form-control" name="prix_nuit" type="number" min="1" step="1" required></div><div class="col-md-4"><label class="form-label">Capacité</label><input class="form-control" name="capacite" type="number" min="1" max="10" value="2"></div><div class="col-md-4"><label class="form-label">Nombre de lits</label><input class="form-control" name="lits" type="number" min="1" value="1"></div><div class="col-md-4"><label class="form-label">Quantité de chambres</label><input class="form-control" name="quantite" type="number" min="1" max="50" value="1"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description_chambre" rows="2"></textarea></div><div class="col-12"><button class="btn btn-primary">Ajouter la chambre +</button></div></form></div><div class="panel"><h2>Mes chambres</h2><div class="table-responsive"><table class="table"><thead><tr><th>Chambre</th><th>Type</th><th>Capacité</th><th>Prix/nuit</th><th>Quantité</th></tr></thead><tbody><?php foreach($rooms as $r):?><tr><td><?=e($r['nom'])?></td><td><?=e($r['type'])?></td><td><?=e($r['capacite'])?></td><td><?=money($r['prix_nuit'])?></td><td><?=e($r['quantite'])?></td></tr><?php endforeach;?><?php if(!$rooms):?><tr><td colspan="5">Ajoutez votre première chambre.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><h2>Réservations reçues</h2><div class="table-responsive"><table class="table"><thead><tr><th>Référence</th><th>Client</th><th>Chambre</th><th>Dates</th><th>Total</th><th>Statut</th></tr></thead><tbody><?php foreach($reservations as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['prenom'].' '.$r['nom'])?></td><td><?=e($r['chambre'])?></td><td><?=e($r['date_arrivee'])?> au <?=e($r['date_depart'])?></td><td><?=money($r['total'])?></td><td><span class="badge-status"><?=e($r['statut'])?></span></td></tr><?php endforeach;?><?php if(!$reservations):?><tr><td colspan="6">Aucune réservation reçue.</td></tr><?php endif;?></tbody></table></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>